<script setup>import{Head,Link,useForm}from'@inertiajs/vue3';import AuthShell from'../../Components/AuthShell.vue';import UiButton from'../../Components/UiButton.vue';const form=useForm({email:'',password:'',remember:false});</script><template><Head title="Sign in"/><AuthShell eyebrow="Welcome back" title="Sign in to your studio" description="Access your secure LensPic workspace."><form class="space-y-5" @submit.prevent="form.post('/login')"><label class="lp-label">Email<input v-model="form.email" type="email" autocomplete="email" class="field mt-2" required><span v-if="form.errors.email" class="lp-error">{{form.errors.email}}</span></label><label class="lp-label">Password<input v-model="form.password" type="password" autocomplete="current-password" class="field mt-2" required><span v-if="form.errors.password" class="lp-error">{{form.errors.password}}</span></label><label class="flex items-center gap-3 text-sm text-slate-600"><input v-model="form.remember" type="checkbox" class="h-4 w-4 accent-indigo">Keep me signed in</label><UiButton type="submit" class="w-full" :loading="form.processing">Sign in</UiButton><p class="text-center text-sm text-slate-600">New to LensPic? <Link href="/register" class="font-semibold text-indigo hover:underline">Create an account</Link></p></form></AuthShell></template>
